INSERT INTO public.node_requirements(node_slug,schema,doc_types) VALUES ('professionals--doctor','{"fields": [{"key": "degree", "label": {"en": "Qualification", "ta": "தகுதி"}, "type": "select", "required": true, "options": ["MBBS", "BDS", "BAMS", "BSMS", "BHMS", "BUMS", "BNYS", "BPT"]}, {"key": "council", "label": {"en": "Registration council", "ta": "பதிவு மன்றம்"}, "type": "select", "required": true, "options": ["Tamil Nadu Medical Council (TNMC)", "National Medical Commission (IMR)"]}, {"key": "reg_no", "label": {"en": "Registration number", "ta": "பதிவு எண்"}, "type": "text", "required": true, "pattern": "^[A-Za-z0-9/ .-]{3,30}$", "placeholder": "e.g. 123456"}, {"key": "reg_year", "label": {"en": "Year of registration", "ta": "பதிவு ஆண்டு"}, "type": "year", "required": true}, {"key": "pg", "label": {"en": "Post-graduate / specialty (optional)", "ta": "முதுநிலை / சிறப்பு (விருப்பம்)"}, "type": "text", "required": false, "placeholder": "e.g. MD Paediatrics"}, {"key": "clinic", "label": {"en": "Hospital / clinic (optional)", "ta": "மருத்துவமனை / கிளினிக் (விருப்பம்)"}, "type": "text", "required": false}], "docs": [{"type": "degree_cert", "label": {"en": "Degree certificate", "ta": "பட்டச் சான்றிதழ்"}, "required": true}, {"type": "council_cert", "label": {"en": "Council registration certificate", "ta": "மன்றப் பதிவுச் சான்றிதழ்"}, "required": true}, {"type": "pg_cert", "label": {"en": "PG / specialty certificate", "ta": "முதுநிலைச் சான்றிதழ்"}, "required": false}, {"type": "experience_letter", "label": {"en": "Experience letter", "ta": "அனுபவக் கடிதம்"}, "required": false}]}'::jsonb,'{degree_cert,council_cert,pg_cert,experience_letter}') ON CONFLICT (node_slug) DO UPDATE SET schema=EXCLUDED.schema, doc_types=EXCLUDED.doc_types;
