INSERT INTO public.node_requirements(node_slug,schema,doc_types) VALUES ('professionals--lawyer','{"fields": [{"key": "degree", "label": {"en": "Law degree", "ta": "சட்டப் பட்டம்"}, "type": "select", "required": true, "options": ["LLB (3-year)", "BA LLB / BBA LLB / BCom LLB (5-year)", "LLM"]}, {"key": "bar_council", "label": {"en": "Bar council", "ta": "வழக்கறிஞர் மன்றம்"}, "type": "select", "required": true, "options": ["Bar Council of Tamil Nadu & Puducherry"]}, {"key": "enrolment_no", "label": {"en": "Enrolment number", "ta": "பதிவு எண்"}, "type": "text", "required": true, "pattern": "^[A-Za-z]{1,4}[ ./-]?[0-9]{1,6}[ ./-]?[0-9]{2,4}$", "placeholder": "e.g. MS/1234/2015", "hint": "As on your enrolment certificate"}, {"key": "enrolment_date", "label": {"en": "Date of enrolment", "ta": "பதிவு தேதி"}, "type": "date", "required": true}, {"key": "cop_no", "label": {"en": "Certificate of Practice no. (if applicable)", "ta": "பயிற்சிச் சான்றிதழ் எண் (இருந்தால்)"}, "type": "text", "required": false}, {"key": "courts", "label": {"en": "Courts you practise in", "ta": "நீங்கள் பணியாற்றும் நீதிமன்றங்கள்"}, "type": "text", "required": false, "placeholder": "e.g. Madras High Court, District Court Nagercoil"}], "docs": [{"type": "degree_cert", "label": {"en": "Law degree certificate", "ta": "சட்டப் பட்டச் சான்றிதழ்"}, "required": true}, {"type": "enrolment_cert", "label": {"en": "Bar Council enrolment certificate", "ta": "பதிவுச் சான்றிதழ்"}, "required": true}, {"type": "cop_cert", "label": {"en": "Certificate of Practice (AIBE)", "ta": "பயிற்சிச் சான்றிதழ் (AIBE)"}, "required": false}, {"type": "bar_id", "label": {"en": "Bar Association ID card", "ta": "வழக்கறிஞர் சங்க அடையாள அட்டை"}, "required": false}]}'::jsonb,'{degree_cert,enrolment_cert,cop_cert,bar_id}') ON CONFLICT (node_slug) DO UPDATE SET schema=EXCLUDED.schema, doc_types=EXCLUDED.doc_types;
INSERT INTO public.node_requirements(node_slug,schema,doc_types) VALUES ('professionals--engineer','{"fields": [{"key": "degree", "label": {"en": "Qualification", "ta": "தகுதி"}, "type": "select", "required": true, "options": ["BE", "BTech", "ME / MTech", "Diploma (DCE/DEEE/DME etc.)"]}, {"key": "discipline", "label": {"en": "Discipline / branch", "ta": "துறை / பிரிவு"}, "type": "text", "required": true, "placeholder": "e.g. Civil, CSE, EEE"}, {"key": "institution", "label": {"en": "College / university", "ta": "கல்லூரி / பல்கலைக்கழகம்"}, "type": "text", "required": false}, {"key": "licence", "label": {"en": "Licence / membership (optional)", "ta": "உரிமம் / உறுப்பினர் (விருப்பம்)"}, "type": "text", "required": false, "placeholder": "e.g. IEI AMIE, Licensed Engineer no."}, {"key": "employer", "label": {"en": "Current employer / firm (optional)", "ta": "தற்போதைய நிறுவனம் (விருப்பம்)"}, "type": "text", "required": false}], "docs": [{"type": "degree_cert", "label": {"en": "Degree / diploma certificate", "ta": "பட்டம் / பட்டயச் சான்றிதழ்"}, "required": true}, {"type": "experience_letter", "label": {"en": "Experience letter(s)", "ta": "அனுபவக் கடிதம்"}, "required": true}, {"type": "licence_cert", "label": {"en": "Licence / membership certificate", "ta": "உரிமச் சான்றிதழ்"}, "required": false}]}'::jsonb,'{degree_cert,experience_letter,licence_cert}') ON CONFLICT (node_slug) DO UPDATE SET schema=EXCLUDED.schema, doc_types=EXCLUDED.doc_types;
INSERT INTO public.node_requirements(node_slug,schema,doc_types) VALUES ('professionals--engineer--architect','{"fields": [{"key": "degree", "label": {"en": "Qualification", "ta": "தகுதி"}, "type": "select", "required": true, "options": ["B.Arch", "M.Arch"]}, {"key": "coa_no", "label": {"en": "Council of Architecture reg. no.", "ta": "கட்டடக் கலை மன்றப் பதிவு எண்"}, "type": "text", "required": true, "pattern": "^CA/[0-9]{4}/[0-9]{3,6}$", "placeholder": "CA/2015/12345"}], "docs": [{"type": "coa_cert", "label": {"en": "COA registration certificate", "ta": "COA பதிவுச் சான்றிதழ்"}, "required": true}]}'::jsonb,'{coa_cert}') ON CONFLICT (node_slug) DO UPDATE SET schema=EXCLUDED.schema, doc_types=EXCLUDED.doc_types;
